-- Oracle 11g additive recommendation data. Existing names/IDs/keywords are preserved.
-- Generated from recommendation-seed.json. Run as one transaction; roll back on any error.
-- No DDL or deletes. New facility purposes apply ONLY to named original DEMO facilities, never actual facilities.
UPDATE FACILITY F SET ROW_VERSION=ROW_VERSION+1 WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-STUDIO01' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X JOIN USE_PURPOSE P ON P.PURPOSE_ID=X.PURPOSE_ID WHERE X.FACILITY_ID=F.FACILITY_ID AND P.PURPOSE_CODE='CONTENT_VIDEO');
