INSERT INTO PURPOSE_EQUIPMENT_RULE(PURPOSE_ID,TYPE_ID,NEED_LEVEL,REASON_TEXT,DISPLAY_ORDER) SELECT P.PURPOSE_ID,T.TYPE_ID,'REQUIRED','활동 영상 기록',1 FROM USE_PURPOSE P CROSS JOIN EQUIPMENT_TYPE T WHERE P.PURPOSE_CODE='CONTENT_VIDEO' AND T.TYPE_NAME='카메라' AND NOT EXISTS(SELECT 1 FROM PURPOSE_EQUIPMENT_RULE R WHERE R.PURPOSE_ID=P.PURPOSE_ID AND R.TYPE_ID=T.TYPE_ID);
INSERT INTO PURPOSE_EQUIPMENT_RULE(PURPOSE_ID,TYPE_ID,NEED_LEVEL,REASON_TEXT,DISPLAY_ORDER) SELECT P.PURPOSE_ID,T.TYPE_ID,'OPTIONAL','대사·내레이션·현장 음성 녹음',1 FROM USE_PURPOSE P CROSS JOIN EQUIPMENT_TYPE T WHERE P.PURPOSE_CODE='CONTENT_VIDEO' AND T.TYPE_NAME='마이크' AND NOT EXISTS(SELECT 1 FROM PURPOSE_EQUIPMENT_RULE R WHERE R.PURPOSE_ID=P.PURPOSE_ID AND R.TYPE_ID=T.TYPE_ID);
INSERT INTO FACILITY_PURPOSE(FACILITY_ID,PURPOSE_ID) SELECT F.FACILITY_ID,P.PURPOSE_ID FROM FACILITY F CROSS JOIN USE_PURPOSE P WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-STUDIO01' AND P.PURPOSE_CODE='CONTENT_VIDEO' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X WHERE X.FACILITY_ID=F.FACILITY_ID AND X.PURPOSE_ID=P.PURPOSE_ID);
INSERT INTO FACILITY_PURPOSE(FACILITY_ID,PURPOSE_ID) SELECT F.FACILITY_ID,P.PURPOSE_ID FROM FACILITY F CROSS JOIN USE_PURPOSE P WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-STUDIO02' AND P.PURPOSE_CODE='CONTENT_VIDEO' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X WHERE X.FACILITY_ID=F.FACILITY_ID AND X.PURPOSE_ID=P.PURPOSE_ID);
INSERT INTO USE_PURPOSE(PURPOSE_ID,PURPOSE_CODE,PURPOSE_NAME,DESCRIPTION_TEXT) SELECT SQ_USE_PURPOSE.NEXTVAL,'JOB_INTERVIEW','면접 연습','모의·취업·화상 면접과 자기소개를 연습할 조용한 공간입니다. 녹화가 필요하면 장비를 선택하세요.' FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM USE_PURPOSE WHERE PURPOSE_CODE='JOB_INTERVIEW');
