INSERT INTO FACILITY_PURPOSE(FACILITY_ID,PURPOSE_ID) SELECT F.FACILITY_ID,P.PURPOSE_ID FROM FACILITY F CROSS JOIN USE_PURPOSE P WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-ROOM01' AND P.PURPOSE_CODE='STUDY' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X WHERE X.FACILITY_ID=F.FACILITY_ID AND X.PURPOSE_ID=P.PURPOSE_ID);
INSERT INTO FACILITY_PURPOSE(FACILITY_ID,PURPOSE_ID) SELECT F.FACILITY_ID,P.PURPOSE_ID FROM FACILITY F CROSS JOIN USE_PURPOSE P WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-ROOM02' AND P.PURPOSE_CODE='STUDY' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X WHERE X.FACILITY_ID=F.FACILITY_ID AND X.PURPOSE_ID=P.PURPOSE_ID);
INSERT INTO FACILITY_PURPOSE(FACILITY_ID,PURPOSE_ID) SELECT F.FACILITY_ID,P.PURPOSE_ID FROM FACILITY F CROSS JOIN USE_PURPOSE P WHERE F.IS_DEMO_YN='Y' AND F.FACILITY_CODE='DEMO-STUDY01' AND P.PURPOSE_CODE='STUDY' AND NOT EXISTS(SELECT 1 FROM FACILITY_PURPOSE X WHERE X.FACILITY_ID=F.FACILITY_ID AND X.PURPOSE_ID=P.PURPOSE_ID);
